from solution import is_tree_balanced


class _Node:
    """Minimal binary-tree node with attribute and item access."""

    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.value = val
        self.data = val
        self.left = left
        self.right = right

    def __getitem__(self, key):
        if key == "left":
            return self.left
        if key == "right":
            return self.right
        if key in ("val", "value", "data"):
            return self.val
        if key == 0:
            return self.val
        if key == 1:
            return self.left
        if key == 2:
            return self.right
        raise KeyError(key)

    def get(self, key, default=None):
        try:
            return self.__getitem__(key)
        except KeyError:
            return default

    def __contains__(self, key):
        return key in ("left", "right", "val", "value", "data", 0, 1, 2)


def test_issue_empty_tree():
    """Empty tree is balanced."""
    assert is_tree_balanced(None) == True  # h=None=0 diff=|0-0|=0 <=1 => True


def test_issue_single_node():
    """Single node tree is balanced."""
    root = _Node()
    assert is_tree_balanced(root) == True  # left_h=0 right_h=0 diff=|0-0|=0 <=1 => True


def test_issue_balanced_two_leaves():
    """Balanced tree has left and right heights within 1."""
    root = _Node(left=_Node(), right=_Node())
    assert is_tree_balanced(root) == True  # left_h=1 right_h=1 diff=|1-1|=0 <=1 => True


def test_issue_boundary_diff_one_still_balanced():
    """Height difference of 1 is still balanced."""
    root = _Node(left=_Node(), right=None)
    assert is_tree_balanced(root) == True  # left_h=1 right_h=0 diff=|1-0|=1 <=1 => True


def test_issue_left_chain_unbalanced():
    """Unbalanced tree returns False."""
    root = _Node(left=_Node(left=_Node()))
    assert is_tree_balanced(root) == False  # left_h=2 right_h=0 diff=|2-0|=2 >1 => False


def test_issue_right_chain_unbalanced():
    """Right-heavy chain with diff 2 is unbalanced."""
    root = _Node(right=_Node(right=_Node()))
    assert is_tree_balanced(root) == False  # left_h=0 right_h=2 diff=|0-2|=2 >1 => False


def test_issue_full_left_empty_right_unbalanced():
    """Height difference of 2 is unbalanced."""
    root = _Node(left=_Node(left=_Node(), right=_Node()), right=None)
    assert is_tree_balanced(root) == False  # left_h=2 right_h=0 diff=|2-0|=2 >1 => False


def test_issue_deep_nested_imbalance():
    """Every subtree must be balanced, not just the root."""
    n2 = _Node(left=_Node(), right=None)
    left_sub = _Node(left=n2, right=None)
    right_sub = _Node(left=_Node(), right=None)
    root = _Node(left=left_sub, right=right_sub)
    assert is_tree_balanced(root) == False  # root diff=|3-2|=1 but sub diff=|2-0|=2 >1 => False


def test_issue_perfect_tree_balanced():
    """Perfect tree with equal heights is balanced."""
    mid_left = _Node(left=_Node(), right=_Node())
    mid_right = _Node(left=_Node(), right=_Node())
    root = _Node(left=mid_left, right=mid_right)
    assert is_tree_balanced(root) == True  # left_h=2 right_h=2 diff=|2-2|=0 <=1 => True


def test_issue_right_deep_unbalanced():
    """Deep right-heavy tree returns False."""
    r3 = _Node()
    r2 = _Node(left=None, right=r3)
    r1 = _Node(left=None, right=r2)
    root = _Node(left=_Node(), right=r1)
    assert is_tree_balanced(root) == False  # diff=|1-3|=2 >1 => False


def test_contract_returns_strict_bool():
    """Balanced check returns a boolean."""
    root = _Node(left=_Node(left=_Node()))
    assert is_tree_balanced(root) is False  # left_h=2 right_h=0 diff=|2-0|=2 >1 => False
